  CONSTRAINT `daily_log_chk_3` CHECK ((`physical_activity_min` between 0 and 1440)),
  CONSTRAINT `daily_log_chk_4` CHECK ((`mood_rating` between 1 and 5))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
